cd /var/www/maestro-studio
python3 -c '
import base64, os, subprocess
b64 = ""
open("source.tar.gz", "wb").write(base64.b64decode(b64))
subprocess.run(["tar", "-xzf", "source.tar.gz"], check=True)
os.remove("source.tar.gz")
print("Sorgenti estratti con successo!")
'
npm install
npm run build
pm2 restart maestro-studio --update-env || PORT=5000 pm2 start server.js --name "maestro-studio"
pm2 save
echo "AGGIORNAMENTO COMPLETATO!"
